(function (all) { var mine = all["hi"] = all["hi"] || {}; var add = {"nav.skip":"सामग्री पर जाएँ","nav.site":"साइट","nav.home":"होम","nav.features":"फ़ीचर्स","nav.documentation":"दस्तावेज़ीकरण","nav.changelog":"बदलाव लॉग","nav.language":"भाषा","hero.tagline":"स्टूडियो की तरह रिकॉर्ड और स्ट्रीम करें — सीन, सोर्स, मल्टीस्ट्रीम, एक साफ़-सुथरे ऐप में।","hero.sub":"Windows, macOS और Linux के लिए लाइव-स्ट्रीमिंग और रिकॉर्डिंग स्टूडियो। न कोई खाता, न टेलीमेट्री, और न हमारी कोई क्लाउड सेवा: आपकी स्ट्रीम सीधे उन प्लेटफ़ॉर्म पर जाती है जिन्हें आप चुनते हैं।","notice.price":"Freally Capture आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","hero.chipDesktop":"डेस्कटॉप ऐप","hero.noDownloads":"वर्तमान रिलीज़ संस्करण 1.2.1 है। इस साइट पर कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","what.title":"यह क्या है","what.p1":"लाइव जाने के लिए आम तौर पर कैप्चर के लिए एक ऐप, आवाज़ मिलाने के लिए दूसरा ऐप, स्ट्रीम को कई प्लेटफ़ॉर्म पर भेजने के लिए एक सेवा, और हर एक पर एक खाता चाहिए होता है।","what.p2":"Freally Capture आपके अपने कंप्यूटर पर एक ही स्टूडियो है। अपनी स्क्रीन, विंडो, कैमरों, मीडिया और ओवरले से सीन बनाइए; उसे ग्राफ़िक्स कार्ड पर जोड़िए; छह तक ऑडियो ट्रैक पर रिकॉर्ड कीजिए; और उसे एक साथ कई प्लेटफ़ॉर्म पर स्ट्रीम कीजिए — सीधे अपनी मशीन से, बीच में किसी रिले के बिना।","what.p3":"इसे खाते की ज़रूरत नहीं और यह कोई टेलीमेट्री नहीं भेजता। आपके कंप्यूटर से बाहर वही जाता है जो स्ट्रीम आपने भेजनी चुनी, और कुछ कनेक्शन जिन्हें आप ख़ुद चालू करते हैं — हर एक दस्तावेज़ीकरण में साफ़-साफ़ लिखा है।","features.title":"इसमें क्या है","features.scenes.title":"GPU पर सीन","features.scenes.body":"डिस्प्ले, विंडो, गेम, कैमरे, वेब पेज, मीडिया, चित्र और टेक्स्ट से सीन बनाइए, और उन्हें फ़िल्टर व ट्रांज़िशन के साथ ग्राफ़िक्स कार्ड पर लाइव जोड़िए।","features.multistream.title":"मल्टीस्ट्रीम, सीधे","features.multistream.body":"Twitch, YouTube, Kick, Facebook, Trovo या अपने ख़ुद के सर्वर पर लाइव जाइए — एक साथ कई पर — RTMP, RTMPS, SRT या WHIP से, सीधे अपनी मशीन से।","features.record.title":"मल्टी-ट्रैक रिकॉर्डिंग","features.record.body":"अपने ग्राफ़िक्स कार्ड के हार्डवेयर एनकोडर से, या Capture के अपने फ़ॉर्मेट में बिना गुणवत्ता खोए रिकॉर्ड कीजिए — छह तक ऑडियो ट्रैक, फ़ाइल विभाजन, चैप्टर मार्कर और क्रैश में भी सुरक्षित फ़ाइलों के साथ।","features.audio.title":"ब्रॉडकास्ट मिक्सर","features.audio.body":"हर सोर्स की अपनी स्ट्रिप, जिसमें शोर दबाना, गेट, कंप्रेसर, EQ और लाउडनेस मापना है — सब पारंपरिक सिग्नल प्रोसेसिंग, कहीं भी AI नहीं।","features.safety.title":"स्टूडियो मोड और सुरक्षा","features.safety.body":"बदलावों को लाइव जाने से पहले प्रीव्यू में तैयार कीजिए, लाइव से पहले की जाँच से सब परखिए, और अलार्म, एनकोडर फ़ेलओवर और पैनिक बटन तैयार रखिए।","features.guests.title":"रिमोट मेहमान","features.guests.body":"एक लिंक से आठ तक मेहमान बुलाइए। वे वेब ब्राउज़र से जुड़ते हैं, और उनका कैमरा व माइक्रोफ़ोन पीयर-टू-पीयर सीधे आप तक पहुँचते हैं।","features.deep.title":"वर्चुअल कैमरा, ब्राउज़र सोर्स, गेम कैप्चर","features.deep.body":"आपका प्रोग्राम वीडियो कॉल के लिए वेबकैम के रूप में, कोई भी वेब पेज सोर्स के रूप में, और एक्सक्लूसिव फ़ुलस्क्रीन गेम — पहले Windows पर, हर कमी साफ़ बताई गई है।","features.free.title":"आज मुफ़्त, लोकल, बिना AI","features.free.body":"न पेड टियर, न खाता, न टेलीमेट्री, न कोई मॉडल। आपके सीन, रिकॉर्डिंग और स्ट्रीम कुंजियाँ आपके कंप्यूटर पर ही रहती हैं।","ladder.title":"संस्करण-दर-संस्करण","ladder.intro":"अब तक के Freally Capture के सभी संस्करण, नींव से लेकर वर्तमान रिलीज़ तक। हर एक का ब्योरा बदलाव लॉग में है।","ladder.version":"संस्करण","ladder.state":"स्थिति","ladder.lands":"क्या लाया","ladder.state.done":"पूरा","ladder.rung.v0.10.0":"नींव: अपने इंजन पर चलने वाला डेस्कटॉप ऐप का ढाँचा, Windows, macOS और Linux पर बिल्ड जाँचें, और यह साइट।","ladder.rung.v0.25.0":"कैप्चर: Windows, macOS और Linux पर स्क्रीन, विंडो और वेबकैम, प्रीव्यू में लाइव।","ladder.rung.v0.40.0":"GPU कंपोज़िटर: सोर्स से बने और ग्राफ़िक्स कार्ड पर जोड़े गए सीन, क्रोमा की, रंग सुधार, LUT और ब्लर जैसे फ़िल्टरों के साथ।","ladder.rung.v0.55.0":"ऑडियो और रिकॉर्डिंग: पारंपरिक DSP फ़िल्टरों वाला छह ट्रैक तक का मिक्सर, और हार्डवेयर एनकोडर व Capture के अपने लॉसलेस फ़ॉर्मेट से मल्टी-ट्रैक रिकॉर्डिंग।","ladder.rung.v0.56.0":"नेटिव GPU प्रीव्यू: प्रोग्राम सीधे कंपोज़िटर से बनाया जाता है, बिना किसी देरी के।","ladder.rung.v0.70.0":"स्टूडियो: अपने-आप फिर से जुड़ने के साथ Twitch, YouTube, Kick, Facebook और Trovo पर स्ट्रीमिंग, ट्रांज़िशन वाला स्टूडियो मोड, हॉटकी, प्रोफ़ाइल और एक आँकड़ा डॉक।","ladder.rung.v0.85.0":"गहरी स्ट्रीमिंग: एक साथ कई प्लेटफ़ॉर्म पर मल्टीस्ट्रीम, SRT और WHIP, वर्टिकल कैनवस, नेस्टेड सीन, रीप्ले बफ़र और बिना साइन-इन वाला चैट ओवरले।","ladder.rung.v0.90.0":"रिमोट कंट्रोल और एक्सटेंशन: पासवर्ड से सुरक्षित WebSocket API, ब्राउज़र डॉक, सैंडबॉक्स में चलने वाली Lua स्क्रिप्ट और प्लगइन SDK — सब लोकल और डिफ़ॉल्ट रूप से बंद।","ladder.rung.v0.95.0":"वितरण: हस्ताक्षरित ऑटो-अपडेटर, हर ऐप्लिकेशन का अलग ऑडियो कैप्चर, और पहली बार चलाने पर लाइसेंस अनुबंध।","ladder.rung.v0.96.0":"सबके लिए स्टूडियो: 18 भाषाएँ, कीबोर्ड और स्क्रीन रीडर का पूरा समर्थन, पहली बार का सेटअप विज़ार्ड, कमांड पैलेट और थीम।","ladder.rung.v0.97.0":"सीन बनाना और निगरानी: पूर्ववत और फिर से करें, OBS सीन संग्रह आयातक, संरेखण गाइड, कीइंग वर्कबेंच, मल्टीव्यू और प्रोजेक्टर।","ladder.rung.v0.98.0":"प्रसारण सुरक्षा: लाइव से पहले की जाँच, अलार्म, सोर्स-हेल्थ डैशबोर्ड, एनकोडर फ़ेलओवर, क्रैश में सुरक्षित रिकॉर्डिंग, पैनिक बटन और बंद करते समय सुरक्षा।","ladder.rung.v0.99.0":"सोर्स, डिवाइस और कैलिब्रेशन: टेस्ट सिग्नल, ऑडियो-वीडियो सिंक कैलिब्रेशन, टाइमर और घड़ियाँ, फ़ाइल से टेक्स्ट, हॉटकी नक्शा, डीइंटरलेसिंग और कैमरा नियंत्रण।","ladder.rung.v0.200.0":"गहरा स्वचालन और कैप्चर: नियम, मैक्रो, MIDI और OSC नियंत्रण, LAN टच पैनल, टैली लाइट, PTZ कैमरे और शो रनडाउन, साथ में पंच-इन ज़ूम और HDR से SDR टोन-मैपिंग।","ladder.rung.v0.300.0":"नए सोर्स और ओवरले: इंस्टेंट रीप्ले, बिना रुकावट की प्लेलिस्ट, टाइटल और स्कोरबोर्ड डिज़ाइनर, ऑडियो विज़ुअलाइज़र, आँकड़ा ओवरले, स्प्लिट टाइमर, इनपुट ओवरले, LAN इनजेस्ट और Freally Link।","ladder.rung.v0.400.0":"गहरा कंपोज़िटर: 3D कॉर्नर-पिन, डाउनस्ट्रीम कीयर, फ़्रीज़-फ़्रेम, और ब्लर, मूव ट्रांज़िशन, WGSL शेडर स्टूडियो, बेज़ियर मास्क और ट्रैक-मैट स्टिंगर।","ladder.rung.v0.500.0":"ऑडियो प्रोडक्शन: आउटपुट रूटिंग, डकिंग मैट्रिक्स, ऑटो-मिक्सर, लाउडनेस नॉर्मलाइज़ेशन, पैरामीट्रिक EQ, साउंडबोर्ड, पॉडकास्ट रिकॉर्डिंग और CLAP व VST3 प्लगइन की खोज।","ladder.rung.v0.600.0":"गहरी रिकॉर्डिंग और रीप्ले: हर सोर्स की ISO रिकॉर्डिंग, क्लिप ट्रिमर, पारदर्शिता के साथ रिकॉर्डिंग, अपने-आप लगने वाले मार्कर, रिकॉर्डिंग के बाद की पाइपलाइन, अखंडता जाँच और SMPTE टाइमकोड।","ladder.rung.v0.700.0":"स्ट्रीमिंग की समझ: नेटवर्क सिम्युलेटर, रिहर्सल मोड, छूटे फ़्रेमों की टाइमलाइन, सत्र रिपोर्ट, एनकोडर बेंचमार्क, और ऐसे सोर्स जो सिर्फ़ स्ट्रीम में या सिर्फ़ रिकॉर्डिंग में दिखें।","ladder.rung.v0.800.0":"रिमोट मेहमान और शो प्रोडक्शन: आठ तक मेहमान, ग्रीन रूम, संकेत, कनेक्शन-गुणवत्ता डैशबोर्ड, टेलीस्ट्रेटर, टेलीप्रॉम्प्टर और अपने-आप बनने वाले मेहमान ग्रिड।","ladder.rung.v0.900.0":"स्टूडियो प्रबंधन: सीन पैक, तुलना और विलय, नाम वाले स्नैपशॉट, पोर्टेबल मोड, एक फ़ाइल में बैकअप, थीम एडिटर और डॉक लेआउट।","ladder.rung.v0.910.0":"नया टेलीप्रॉम्प्टर: विराम चिप, शुरुआती उलटी गिनती, BPM गति, ज़ोर से पढ़ना, और सभी 18 भाषाओं में ऑटोकम्प्लीट।","ladder.rung.v1.0.0":"पहली स्थिर रिलीज़: हर नियोजित फ़ीचर, साथ में \"जल्द शुरू होगा\" उलटी गिनती, बैकग्राउंड म्यूज़िक, सोशल बार और चुने हुए चैट संदेश का बैनर।","ladder.rung.v1.1.0":"साझा करने लायक़ एक MP4, जो हर लॉसलेस रिकॉर्डिंग के रुकने पर उसके बगल में लिखा जाता है।","ladder.rung.v1.2.0":"गहरा कैप्चर और वेब: वर्चुअल कैमरा, असली ब्राउज़र सोर्स और गेम कैप्चर, पहले Windows पर।","ladder.rung.v1.2.1":"ऑडिट: कोई नया फ़ीचर नहीं, सुरक्षा और सही काम करने की पूरी जाँच, और 1.2.0 में जोड़े गए तीनों फ़ीचर अब सचमुच काम करते हैं।","ladder.note":"सूची का हर संस्करण पूरा है। 1.2.1 के बाद क्या आएगा, इसकी योजना निजी रूप से बनती है और रिलीज़ होने पर यहाँ दिखेगी। इनमें से कोई भी इस साइट पर डाउनलोड नहीं है।","honest.title":"वे बातें जिन्हें ज़्यादातर साइटें सबसे नीचे रखती हैं","honest.windows.title":"कुछ नए फ़ीचर सिर्फ़ Windows पर हैं","honest.windows.body":"1.2.1 में वर्चुअल कैमरा, गेम कैप्चर और कर्सर इफ़ेक्ट सिर्फ़ Windows पर काम करते हैं, और ब्राउज़र सोर्स को पहले Windows पर परखा गया है। बाक़ी स्टूडियो Windows, macOS और Linux पर चलता है।","honest.signed.title":"दो कंपोनेंट अभी कोड-साइन नहीं हैं","honest.signed.body":"वर्चुअल कैमरे का सिस्टम कंपोनेंट और ब्राउज़र सोर्स का रनटाइम अभी कोड-साइन नहीं हैं, और दो लाइव परीक्षण बाक़ी हैं: असली वीडियो कॉल में कैमरा, और सुरक्षित गेम में गेम कैप्चर। बदलाव लॉग उन्हें जोड़ने वाली रिलीज़ में यह बताता है।","honest.network.title":"असल में क्या ऑनलाइन जाता है","honest.network.body":"आपकी स्ट्रीम उन प्लेटफ़ॉर्म पर जाती हैं जिन्हें आप सेट करते हैं। मेहमानों वाले सत्र का कनेक्शन बनना एक सार्वजनिक सिग्नलिंग सेवा से होकर जाता है; चैट ओवरले किसी चैनल की सार्वजनिक चैट पढ़ता है; ffmpeg और ब्राउज़र रनटाइम पहली बार ज़रूरत पड़ने पर डाउनलोड होते हैं; ऐप अपडेट जाँचता है; और समस्या की रिपोर्ट तभी जाती है जब आप उसके पेज पर भेजें दबाते हैं। अपडेट जाँच के अलावा, इनमें से हर चीज़ तभी होती है जब आपने उसे सेट किया हो।","honest.downloads.title":"यहाँ कोई डाउनलोड नहीं","honest.downloads.body":"यह साइट Freally Capture के बारे में बताती है; इसे बाँटती नहीं। न कोई डाउनलोड पेज है, न लिंक, न बटन, और सोर्स कोड निजी है।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © Mike Weaver. आज उपयोग के लिए मुफ़्त; भविष्य के संस्करण बेचे जा सकते हैं। ओपन सोर्स नहीं।","footer.yours":"आप जो रिकॉर्ड और स्ट्रीम करते हैं वह आपका है, और उसकी ज़िम्मेदारी भी। Freally Capture के लेखक उसमें से कुछ भी न पाते हैं, न सहेजते हैं, न आगे भेजते हैं।","featuresPage.title":"यह क्या-क्या करता है","featuresPage.lead":"आपके अपने कंप्यूटर पर लाइव-स्ट्रीमिंग और रिकॉर्डिंग स्टूडियो: ग्राफ़िक्स कार्ड पर जुड़े सीन, मल्टी-ट्रैक रिकॉर्डिंग, और सीधे आपकी मशीन से एक साथ सभी प्लेटफ़ॉर्म पर मल्टीस्ट्रीम।","featuresPage.version":"यह पेज जारी हो चुके संस्करण Freally Capture 1.2.1 का वर्णन करता है: इस पर जो कुछ है वह 1.2.1 में है, और बाद के लिए नियोजित कुछ भी इस पर नहीं है।","featuresPage.numbers.title":"आँकड़ों में","featuresPage.numbers.intro":"हर आँकड़ा वही है जो संस्करण 1.2.1 करता है, इसके कोड और बदलाव लॉग से गिना गया। कुछ भी बढ़ाकर नहीं लिखा गया।","featuresPage.numbers.systems":"ऑपरेटिंग सिस्टम: Windows, macOS और Linux","featuresPage.numbers.protocols":"स्ट्रीमिंग प्रोटोकॉल: RTMP, RTMPS, SRT और WHIP","featuresPage.numbers.platforms":"बिल्ट-इन प्लेटफ़ॉर्म — Twitch, YouTube, Kick, Facebook और Trovo — और आपका कोई भी अपना सर्वर","featuresPage.numbers.tracks":"ऑडियो ट्रैक, एक रिकॉर्डिंग में","featuresPage.numbers.encoders":"हार्डवेयर एनकोडर परिवार: NVENC, Quick Sync, AMF, VAAPI और VideoToolbox","featuresPage.numbers.guests":"रिमोट मेहमान, एक सत्र में","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.accounts":"खाते बनाने की ज़रूरत","featuresPage.numbers.ai":"AI मॉडल","featuresPage.numbers.price":"आज की क़ीमत","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Freally Capture आज जो कुछ करता है वह सबके लिए मुफ़्त है: न पेड टियर, न सदस्यता, न खाता, न वॉटरमार्क और न ख़त्म होने वाला ट्रायल। आप जो रिकॉर्ड और स्ट्रीम करते हैं वह आपका है।","featuresPage.cards.title":"संस्करण 1.2.1 क्या करता है","featuresPage.cards.scenes.title":"GPU पर सीन और सोर्स","featuresPage.cards.scenes.body":"डिस्प्ले, विंडो, गेम, वेबकैम और कैप्चर कार्ड, वेब पेज, मीडिया, प्लेलिस्ट, चित्र, टेक्स्ट, टाइमर और टेस्ट सिग्नल, ग्राफ़िक्स कार्ड पर लाइव जोड़े गए। नेस्टेड सीन, समूह, साझा सोर्स, 9:16 वर्टिकल कैनवस, और हर बदलाव को पूर्ववत करने की सुविधा।","featuresPage.cards.effects.title":"फ़िल्टर और ट्रांज़िशन","featuresPage.cards.effects.body":"हर सोर्स पर क्रोमा की, रंग सुधार, LUT, मास्क, कई तरह के ब्लर, 3D झुकाव और आपके अपने WGSL शेडर। कट, फ़ेड, स्लाइड, स्टिंगर, ल्यूमा वाइप, और एक मूव ट्रांज़िशन जो चीज़ों को एक सीन से दूसरे सीन में सरकाता है।","featuresPage.cards.studio.title":"स्टूडियो मोड और निगरानी","featuresPage.cards.studio.body":"अगला शॉट प्रीव्यू में तैयार कीजिए और तैयार होने पर प्रोग्राम में भेजिए। मल्टीव्यू, किसी भी डिस्प्ले पर फ़ुलस्क्रीन प्रोजेक्टर, हर सीन के ऊपर डाउनस्ट्रीम कीयर, और असली आँकड़े दिखाने वाला आँकड़ा डॉक।","featuresPage.cards.multistream.title":"मल्टीस्ट्रीम, सीधे आपकी मशीन से","featuresPage.cards.multistream.body":"RTMP, RTMPS, SRT या WHIP से एक साथ कई प्लेटफ़ॉर्म पर लाइव जाइए, बीच में किसी रिले सेवा के बिना। हर गंतव्य ख़ुद फिर से जुड़ता है, इसलिए एक के गिरने से बाक़ी कभी नहीं गिरते।","featuresPage.cards.recording.title":"टिकाऊ रिकॉर्डिंग","featuresPage.cards.recording.body":"हार्डवेयर एनकोडर, बैकअप के रूप में x264, MP4, MKV, MOV या WebM में, या Capture के अपने लॉसलेस फ़ॉर्मेट में; छह तक ऑडियो ट्रैक; हर सोर्स की साफ़ फ़ाइल; क्रैश झेल जाने वाली रिकॉर्डिंग, और अगली बार खोलने पर मरम्मत।","featuresPage.cards.audio.title":"ब्रॉडकास्ट ऑडियो कंसोल","featuresPage.cards.audio.body":"हर स्ट्रिप पर शोर दबाना, गेट, कंप्रेसर, लिमिटर, पैरामीट्रिक EQ और डी-एसर, साथ में डकिंग, ऑटो-मिक्सर, लाउडनेस नॉर्मलाइज़ेशन, साउंडबोर्ड और पॉडकास्ट रिकॉर्डिंग। पारंपरिक सिग्नल प्रोसेसिंग, बिना AI।","featuresPage.cards.replay.title":"इंस्टेंट रीप्ले","featuresPage.cards.replay.body":"लगातार चलने वाला रीप्ले बफ़र जो एक बटन से पिछले पल सहेज लेता है, और एक रीप्ले सोर्स जो उन्हें पूरी, आधी या चौथाई गति पर शो में वापस लाता है। क्लिप ट्रिमर जहाँ हो सके बिना री-एनकोड किए एक्सपोर्ट करता है।","featuresPage.cards.guests.title":"ब्राउज़र से मेहमान","featuresPage.cards.guests.body":"आठ तक मेहमान बिना कुछ इंस्टॉल किए, वेब ब्राउज़र में एक लिंक से जुड़ते हैं। ग्रीन रूम, निजी संकेत, हर मेहमान का कनेक्शन एक नज़र में, और नाम-पट्टियों वाला अपने-आप बनने वाला ग्रिड।","featuresPage.cards.safety.title":"प्रसारण सुरक्षा","featuresPage.cards.safety.body":"लाइव से पहले की जाँच; सन्नाटा, क्लिपिंग, जमी हुई तस्वीर और भरती डिस्क के अलार्म; शो के बीच एनकोडर फ़ेलओवर; पैनिक बटन; कुछ न भेजने वाला रिहर्सल मोड; और सब कुछ क्रम से समेटकर बंद होना।","featuresPage.cards.automation.title":"स्वचालन और नियंत्रण","featuresPage.cards.automation.body":"नियम, मैक्रो और वेरिएबल; MIDI और OSC कंट्रोलर; आपके फ़ोन पर टच पैनल और टैली लाइट; PTZ कैमरे; शो रनडाउन; Stream Deck के लिए WebSocket API; Lua स्क्रिप्ट और प्लगइन। सब डिफ़ॉल्ट रूप से बंद।","featuresPage.cards.deep.title":"वर्चुअल कैमरा, ब्राउज़र सोर्स, गेम कैप्चर","featuresPage.cards.deep.body":"आपका प्रोग्राम वीडियो-कॉल ऐप के लिए वेबकैम के रूप में; कोई भी वेब पेज सोर्स के रूप में रेंडर; और एक्सक्लूसिव फ़ुलस्क्रीन गेम एक हुक के ज़रिए जिसे आप हर गेम के लिए अलग से मंज़ूरी देते हैं। पहले Windows पर, कमियाँ नीचे बताई गई हैं।","featuresPage.cards.private.title":"लोकल, निजी, बिना AI","featuresPage.cards.private.body":"न खाता, न टेलीमेट्री, और न हमारी कोई क्लाउड सेवा। आपकी रिकॉर्डिंग और स्ट्रीम कुंजियाँ आपके कंप्यूटर पर रहती हैं, और कोई भी फ़िल्टर मॉडल का उपयोग नहीं करता: हर एक पारंपरिक सिग्नल प्रोसेसिंग है।","featuresPage.compare.title":"व्यावसायिक स्टूडियो के साथ तुलना","featuresPage.compare.intro":"Freally Capture उन व्यावसायिक स्टूडियो के साथ जिनसे लोग स्ट्रीम और रिकॉर्ड करते हैं। Capture का कॉलम जारी हो चुका संस्करण 1.2.1 है। किसी दूसरे उत्पाद का हर सेल उसके निर्माता के अपने पेजों से लिया गया है, जिन्हें 2 अक्टूबर 2026 को जाँचा गया, और क़ीमतें अक्टूबर 2026 की अमेरिकी सूची क़ीमतें हैं।","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.legend.partly":"आंशिक","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.legend.unknown":"सत्यापित नहीं","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.price":"क़ीमत (USD, अक्टूबर 2026)","featuresPage.compare.freeToday":"आज मुफ़्त","featuresPage.compare.price.streamlabs":"$27 प्रति माह या $189 प्रति वर्ष","featuresPage.compare.price.xsplit":"$14.99 प्रति माह, $59.99 प्रति वर्ष या एक बार में $119.99","featuresPage.compare.price.vmix":"एक बार में $1,200","featuresPage.compare.price.wirecast":"$79 प्रति माह, या $504 प्रति वर्ष","featuresPage.compare.price.ecamm":"$40 प्रति माह या $384 प्रति वर्ष","featuresPage.compare.price.restream":"$19 प्रति माह या $190 प्रति वर्ष","featuresPage.compare.row.systems":"Windows, macOS और Linux पर चलता है","featuresPage.compare.note.browser":"वेब ब्राउज़र में","featuresPage.compare.row.multistream":"एक साथ कई प्लेटफ़ॉर्म पर स्ट्रीम","featuresPage.compare.note.channels3":"इस प्लान में 3 चैनल","featuresPage.compare.row.direct":"…सीधे आपके कंप्यूटर से, बीच में किसी रिले सेवा के बिना","featuresPage.compare.note.servers":"निर्माता के सर्वरों से होकर","featuresPage.compare.row.srt":"SRT आउटपुट","featuresPage.compare.note.business":"Business प्लान और ऊपर","featuresPage.compare.row.whip":"WHIP (WebRTC) आउटपुट","featuresPage.compare.note.customStream":"\"Custom Stream\" आउटपुट","featuresPage.compare.note.beta":"बीटा में","featuresPage.compare.row.vcam":"वीडियो कॉल के लिए वर्चुअल कैमरा","featuresPage.compare.note.windowsOnly":"फ़िलहाल सिर्फ़ Windows","featuresPage.compare.row.guests":"मेहमान वेब ब्राउज़र से जुड़ते हैं","featuresPage.compare.note.p2p":"8 तक, पीयर-टू-पीयर","featuresPage.compare.note.collab":"11 तक मेहमान या कैमरे","featuresPage.compare.note.vmixCall":"8 तक, vMix Call से","featuresPage.compare.note.rendezvous":"7 तक, Rendezvous से","featuresPage.compare.note.ecammGuests":"Apple Silicon पर 10 तक","featuresPage.compare.note.restreamGuests":"स्क्रीन पर 10, होस्ट समेत","featuresPage.compare.row.replay":"इंस्टेंट रीप्ले","featuresPage.compare.row.tracks":"एक रिकॉर्डिंग में कई ऑडियो ट्रैक","featuresPage.compare.note.tracks6":"6 ट्रैक तक","featuresPage.compare.note.tracks5":"5 ट्रैक","featuresPage.compare.note.channels":"चैनलों के रूप में, सिर्फ़ AVI या WAV","featuresPage.compare.note.tracks8":"8 ट्रैक तक","featuresPage.compare.note.separateFiles":"अलग फ़ाइलों के रूप में","featuresPage.compare.note.professional":"Professional प्लान और ऊपर","featuresPage.compare.row.account":"बिना खाते के काम करता है","featuresPage.compare.note.recordingOnly":"सिर्फ़ रिकॉर्डिंग के लिए","featuresPage.compare.note.licenceAccount":"लाइसेंस खाते से बँधा","featuresPage.compare.note.key":"एक लाइसेंस कुंजी","featuresPage.compare.note.signIn":"साइन-इन ज़रूरी","featuresPage.compare.row.noAi":"कोई AI फ़ीचर नहीं","featuresPage.compare.note.aiHighlights":"AI से गेम हाइलाइट","featuresPage.compare.note.aiBackground":"AI से बैकग्राउंड हटाना","featuresPage.compare.note.aiClips":"AI क्लिप और संगीत","featuresPage.compare.summary":"Freally Capture के पास जो है और दूसरों के पास नहीं: यहाँ यही अकेला डेस्कटॉप ऐप है जो Windows और macOS के साथ Linux पर भी चलता है, और यही अकेला मुफ़्त है। छह में से चार को खाता चाहिए और चार में AI फ़ीचर हैं; Capture में दोनों में से कुछ नहीं, और यह सीधे आपके कंप्यूटर से कई प्लेटफ़ॉर्म पर स्ट्रीम करता है, जबकि Streamlabs और Restream आपकी स्ट्रीम अपने सर्वरों से होकर भेजते हैं।","featuresPage.compare.theyWin":"जहाँ वे आगे हैं: Wirecast Pro 8 तक ऑडियो ट्रैक रिकॉर्ड करता है, Capture 6, और Streamlabs Ultra 11 तक मेहमान या कैमरे लेता है और Ecamm 10 तक, Capture 8। Streamlabs, XSplit, vMix, Wirecast और Ecamm सभी में वर्चुअल कैमरा है; Capture का वर्चुअल कैमरा 1.2.1 में सिर्फ़ Windows पर चलता है और अभी कोड-साइन नहीं है।","featuresPage.compare.obs":"OBS Studio भी मुफ़्त और ओपन सोर्स है, तीनों सिस्टम पर चलता है, और उसमें SRT, WHIP, वर्चुअल कैमरा, रीप्ले बफ़र और छह ऑडियो ट्रैक हैं। एक साथ कई प्लेटफ़ॉर्म पर स्ट्रीम करने के लिए उसे तीसरे पक्ष का प्लगइन चाहिए; Capture में यह पहले से है, ब्राउज़र से जुड़ने वाले मेहमानों की तरह।","featuresPage.compare.asOf":"Capture की क़ीमत आज की है: यह आज मुफ़्त है, और भविष्य के संस्करण बेचे जा सकते हैं। दूसरे उत्पाद भी बदलते हैं; यह तालिका 2 अक्टूबर 2026 की स्थिति दिखाती है।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"स्ट्रीमिंग टूल को कभी \"अपना चैनल जोड़ें\" नहीं बनना चाहिए। न बनाने को कोई खाता है, न बीच में हमारा कोई रिले: आपकी स्ट्रीम आपके कंप्यूटर से आपके चुने प्लेटफ़ॉर्म तक जाती है।","featuresPage.why.owned.title":"अपना इंजन","featuresPage.why.owned.body":"कंपोज़िटर, ऑडियो इंजन और लॉसलेस रिकॉर्डिंग फ़ॉर्मेट Capture के अपने हैं। प्लेटफ़ॉर्म जिन कोडेक की माँग करते हैं वे ffmpeg से आते हैं, जो साथ बंडल होने के बजाय पहली बार ज़रूरत पड़ने पर डाउनलोड होता है।","featuresPage.why.dsp.title":"पारंपरिक सिग्नल प्रोसेसिंग","featuresPage.why.dsp.body":"शोर दबाना, कीइंग और टोन-मैपिंग सूत्र हैं, मॉडल नहीं। वही इनपुट और वही सेटिंग्स वही नतीजा देती हैं, और उन्हें चलाने के लिए कुछ भी डाउनलोड नहीं करना पड़ता।","featuresPage.why.safe.title":"जब तक आप चालू न करें, बंद","featuresPage.why.safe.body":"हर नेटवर्क लिसनर, हर स्वचालन और हर जोखिम भरा कैप्चर डिफ़ॉल्ट रूप से बंद है। गेम कैप्चर हर गेम के लिए आपसे पूछता है, और कोई साझा सीन संग्रह उस अनुमति को कभी साथ नहीं ला सकता।","featuresPage.why.honest.title":"अपनी कमियों के बारे में ईमानदार","featuresPage.why.honest.body":"जब कोई फ़ीचर सिर्फ़ एक सिस्टम पर चलता है, अभी कोड-साइन नहीं है, या उसका लाइव परीक्षण बाक़ी है, तो ऐप, बदलाव लॉग और यह पेज यह बताते हैं।","featuresPage.limits.title":"1.2.1 क्या नहीं करता","featuresPage.limits.vcam":"वर्चुअल कैमरा सिर्फ़ Windows पर काम करता है; macOS और Linux के कैमरे इस रिलीज़ में नहीं हैं।","featuresPage.limits.game":"गेम कैप्चर सिर्फ़ Windows पर काम करता है और Direct3D 11 गेम कॉपी करता है; HDR और Direct3D 12 गेम विंडो कैप्चर पर चले जाते हैं।","featuresPage.limits.browser":"ब्राउज़र सोर्स किसी पेज की तस्वीर दिखाता है, लेकिन अभी उसकी आवाज़ नहीं।","featuresPage.limits.signed":"वर्चुअल कैमरे का सिस्टम कंपोनेंट और ब्राउज़र रनटाइम अभी कोड-साइन नहीं हैं, और दो लाइव परीक्षण बाक़ी हैं: असली वीडियो कॉल में कैमरा, और सुरक्षित गेम में गेम कैप्चर।","featuresPage.limits.cursor":"कर्सर इफ़ेक्ट और कीबोर्ड-माउस इनपुट ओवरले सिर्फ़ Windows पर काम करते हैं।","featuresPage.limits.ai":"इसमें कोई AI फ़ीचर नहीं है — न AI से बैकग्राउंड हटाना, न कैप्शन, न हाइलाइट क्लिप — और ऐसा जान-बूझकर है।","featuresPage.limits.downloads":"इस साइट पर कोई डाउनलोड नहीं है, और इस पेज पर भी नहीं।","docs.title":"दस्तावेज़ीकरण","docs.intro":"Freally Capture संस्करण 1.2.1 कैसे इस्तेमाल करें: सीन बनाना, उसे रिकॉर्ड करना, लाइव जाना, और इनके आस-पास का सब कुछ। जब कोई फ़ीचर तीनों सिस्टम पर नहीं चलता, तो हर खंड बताता है कि वह किन पर चलता है।","search.placeholder":"दस्तावेज़ीकरण में खोजें","docs.contents":"विषय-सूची","join.title":"रिमोट मेहमान के रूप में जुड़ें","join.button.join":"कैमरा और माइक के साथ जुड़ें","join.button.leave":"छोड़ें","join.greenRoom":"आप ग्रीन रूम में हैं — होस्ट आपका कैमरा और माइक जाँच रहे हैं। आप जल्द ही ऑन एयर होंगे।","join.cue":"संकेत","join.selfLabel":"आप — होस्ट को यही दिखता है।","join.hostSharing":"होस्ट अपना दृश्य साझा कर रहे हैं।","join.fine":"जब तक आप जुड़ें पर टैप नहीं करते, कुछ भी कनेक्ट नहीं होता। आपका कैमरा और माइक्रोफ़ोन सीधे होस्ट तक जाते हैं, WebRTC पर पीयर-टू-पीयर और रास्ते में एन्क्रिप्टेड; सिर्फ़ कनेक्शन बनाने की प्रक्रिया एक सार्वजनिक सिग्नलिंग सेवा से होकर जाती है। यह पेज आपके ब्राउज़र में चलता है और और कुछ भी अपलोड नहीं करता। होस्ट आपको सुन सकते हैं, ऑन एयर ला सकते हैं, म्यूट कर सकते हैं या हटा सकते हैं, और आप उनकी हर रिकॉर्डिंग या स्ट्रीम का हिस्सा होते हैं।","join.appPrompt":"क्या Freally Capture इंस्टॉल है?","join.appLink":"इसके बजाय यह आमंत्रण ऐप में खोलें","join.status.checking":"आपका आमंत्रण जाँचा जा रहा है…","join.seconds":"{{n}} सेकंड","join.hours":"{{n}} घंटे","join.minutes":"{{n}} मिनट","join.status.invited":"आप आमंत्रित हैं। आमंत्रण लगभग {{time}} और मान्य है — तैयार हों तो जुड़ें पर टैप करें।","join.status.expired":"इस आमंत्रण की अवधि ख़त्म हो गई है — होस्ट से नया लिंक माँगें।","join.status.missing":"इस लिंक में कोई आमंत्रण नहीं है — होस्ट का साझा किया हुआ लिंक या QR कोड ठीक वैसा ही खोलें।","join.status.damaged":"यह आमंत्रण ख़राब लग रहा है — होस्ट से लिंक दोबारा साझा करने को कहें।","join.button.mutedByHost":"होस्ट ने म्यूट किया","join.button.unmute":"मेरा माइक चालू करें","join.button.mute":"मेरा माइक म्यूट करें","join.button.stopShare":"साझा करना रोकें","join.button.share":"मेरी स्क्रीन साझा करें","join.status.noReconnect":"फिर से नहीं जुड़ सके — आमंत्रण मान्य रहते हुए यह पेज रीलोड करें और दोबारा जुड़ें।","join.status.reconnecting":"कनेक्शन टूट गया — {{seconds}} सेकंड में फिर से जुड़ रहे हैं (कोशिश {{attempt}}/{{max}})…","join.status.requesting":"आपके कैमरा और माइक्रोफ़ोन की अनुमति माँगी जा रही है…","join.status.blocked":"कैमरा या माइक्रोफ़ोन ब्लॉक है: {{error}} — अनुमति दें और फिर से जुड़ें पर टैप करें।","join.status.reconnectedMuted":"फिर से जुड़ गए — आपका माइक म्यूट ही रहेगा (आपने ख़ुद म्यूट किया था)।","join.status.calling":"होस्ट को कॉल किया जा रहा है…","join.status.hostMuted":"होस्ट ने आपको म्यूट किया।","join.status.hostUnmuted":"होस्ट ने आपका म्यूट हटाया।","join.status.removed":"होस्ट ने आपको हटा दिया — दोबारा आमंत्रित होने पर लिंक अब भी काम करेगा।","join.status.banned":"होस्ट ने आपको इस सत्र से हटा दिया।","join.status.ended":"होस्ट ने सत्र समाप्त कर दिया।","join.status.callError":"कॉल त्रुटि: {{error}}","join.status.iceFailed":"सीधा कनेक्शन नहीं बन सका — दोनों तरफ़ सख़्त NAT हैं। होस्ट अपने Remote डायलॉग में TURN रिले सेट कर सकते हैं।","join.status.unstable":"कनेक्शन अस्थिर है — ठीक करने की कोशिश हो रही है…","join.status.connected":"जुड़ गए — आपका कैमरा और माइक साझा हो रहा है। यह पेज खुला रखें।","join.status.signallingLost":"सिग्नलिंग टूट गई — फिर से जुड़ रहे हैं (आपकी तस्वीर और आवाज़ जारी है)…","join.status.hostUnreachable":"होस्ट तक नहीं पहुँच पा रहे — क्या उनका सत्र अब भी चल रहा है?","join.status.connectionError":"कनेक्शन त्रुटि: {{error}}","join.status.shareBlocked":"स्क्रीन साझा करना ब्लॉक है: {{error}}","join.status.sharing":"आपकी स्क्रीन सत्र में साझा हो रही है।","join.status.left":"आपने सत्र छोड़ दिया।"}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
